import './ActivityContent.css';

import { Link } from "react-router-dom";
import { timeAgo, formatTimeExpires } from '../lib/DateTimeFormats';
import {ReactComponent as BombIcon} from './svg/bomb.svg';
import ProfileAvatar from './ProfileAvatar';
import { renderEmoji } from '../lib/emoji';

// Splits a message into plain text, links and #hashtags. split() with a
// capturing group keeps the matches at the odd indexes. Links come first in
// the alternation so a '#' inside a URL stays part of the link. Everything is
// built as React elements, never as an HTML string, so a message cannot
// inject markup (XSS). Hashtags: backlog #41. Links: backlog #46.
// Plain-text pieces also get their emoji enlarged 20% (backlog #51).
const TOKEN_SPLIT = /(https?:\/\/[^\s<>"]+|#[\p{L}\p{N}_]+)/iu;
const LINK_START = /^https?:\/\//i;
const TRAILING_PUNCT = /[.,!?;:'"]$/;
const LINK_DISPLAY_MAX = 40;

// "see https://example.com." -> the period is sentence punctuation, not part
// of the link. A closing ")" is trimmed only when it has no matching "(",
// so Wikipedia-style links such as /wiki/Foo_(bar) stay whole.
function splitTrailing(raw) {
  let url = raw;
  let trail = '';
  for (;;) {
    const last = url.slice(-1);
    const unbalanced = last === ')' &&
      url.split(')').length > url.split('(').length;
    if (TRAILING_PUNCT.test(url) || unbalanced) {
      trail = last + trail;
      url = url.slice(0, -1);
    } else {
      return [url, trail];
    }
  }
}

function renderLink(raw, key) {
  const [url, trail] = splitTrailing(raw);
  let href = null;
  try {
    const parsed = new URL(url);
    // Only web links become clickable; anything else stays plain text.
    if (parsed.protocol === 'http:' || parsed.protocol === 'https:') {
      href = parsed.href;
    }
  } catch (e) {
    href = null;
  }
  if (!href) {
    return raw;
  }
  const bare = Array.from(url.replace(LINK_START, ''));
  const display = bare.length > LINK_DISPLAY_MAX
    ? bare.slice(0, LINK_DISPLAY_MAX).join('') + '\u2026'
    : bare.join('');
  return (
    <span key={key}>
      <a
        className='link'
        href={href}
        title={url}
        target='_blank'
        rel='noopener noreferrer nofollow'
        onClick={(e) => e.stopPropagation()}
      >{display}</a>{trail}
    </span>
  );
}

function renderMessage(message) {
  if (typeof message !== 'string' || message === '') {
    return message;
  }
  return message.split(TOKEN_SPLIT).map((part, i) => {
    if (i % 2 === 0) {
      return renderEmoji(part, `t${i}`);
    }
    if (LINK_START.test(part)) {
      return renderLink(part, i);
    }
    return <span className='hashtag' key={i}>{part}</span>;
  });
}

export default function ActivityContent(props) {

  // formatTimeExpires returns null once the post has expired; the countdown
  // is then hidden rather than shown as negative minutes (backlog #25).
  let expires_at;
  const expires_label = props.activity.expires_at
    ? formatTimeExpires(props.activity.expires_at)
    : null;
  if (expires_label) {
    expires_at =  <div className="expires_at" title={props.activity.expires_at}>
                    <BombIcon className='icon' />
                    <span className='ago'>{expires_label}</span>
                  </div>

  }

  // Profile feeds list replies on their own, so show which post each one
  // answers (backlog #29). The API sends reply_to only on the profile feed;
  // the preview is already cut to 80 characters server-side, and CSS keeps
  // the line to one row. Plain text, not renderMessage: no links in a preview.
  let replyTo;
  const parent = props.activity.reply_to;
  if (parent && parent.handle) {
    replyTo = <div className='reply_to' title={parent.preview}>
                {'\u21B3 Replying to '}
                <Link to={`/@`+parent.handle}>@{parent.handle}</Link>
                {parent.preview ? ': ' + parent.preview : ''}
              </div>
  }

  return (
    <div className='activity_content_wrap'>
      <div className='activity_avatar'>
  <ProfileAvatar id={props.activity.cognito_user_id} name={props.activity.display_name} />
</div>
      <div className='activity_content'>
        <div className='activity_meta'>
          <Link className='activity_identity' to={`/@`+props.activity.handle}>
            <div className='display_name'>{props.activity.display_name}</div>
            <div className="handle">@{props.activity.handle}</div>
          </Link>{/* activity_identity */}
          <div className='activity_times'>
            <div className="created_at" title={props.activity.created_at}>
              <span className='ago'>{timeAgo(props.activity.created_at)}</span> 
            </div>
            {expires_at}
          </div>{/* activity_times */}
        </div>{/* activity_meta */}
        {replyTo}
        <div className="message">{renderMessage(props.activity.message)}</div>
      </div>{/* activity_content */}
    </div>
  );
}

import './MessageItem.css';
import { Link } from "react-router-dom";
import { timeAgo } from '../lib/DateTimeFormats';
import ProfileAvatar from './ProfileAvatar';
import { renderEmoji } from '../lib/emoji';

export default function MessageItem(props) {

  return (
    <Link className='message_item' to={`/@`+props.message.handle}>
      <div className='message_avatar'>
        <ProfileAvatar id={props.message.cognito_user_id} name={props.message.display_name} />
      </div>
      <div className='message_content'>
        <div className='message_meta'>
          <div className='message_identity'>
            <div className='display_name'>{props.message.display_name}</div>
            <div className="handle">@{props.message.handle}</div>
          </div>{/* activity_identity */}
        </div>{/* message_meta */}
        <div className="message">{renderEmoji(props.message.message, 'm')}</div>
        <div className="created_at" title={props.message.created_at}>
          <span className='ago'>{timeAgo(props.message.created_at)}</span> 
        </div>{/* created_at */}
      </div>{/* message_content */}
    </Link>
  );
}

import './MessageGroupItem.css';
import { Link } from "react-router-dom";
import { timeAgo } from '../lib/DateTimeFormats';
import { useParams } from 'react-router-dom';
import ProfileAvatar from './ProfileAvatar';
import { renderEmoji } from '../lib/emoji';

export default function MessageGroupItem(props) {
  const params = useParams();


  const classes = () => {
    let classes = ["message_group_item"];
    if (params.message_group_uuid == props.message_group.uuid){
      classes.push('active')
    }
    return classes.join(' ');
  }

  return (
    <Link className={classes()} to={`/messages/`+props.message_group.uuid}>
      <div className='message_group_avatar'>
        <ProfileAvatar
          id={props.message_group.cognito_user_id}
          name={props.message_group.display_name}
        />
      </div>
      <div className='message_content'>
        <div className='message_group_meta'>
          <div className='message_group_identity'>
            <div className='display_name'>{props.message_group.display_name}</div>
            <div className="handle">@{props.message_group.handle}</div>
          </div>{/* activity_identity */}
        </div>{/* message_meta */}
        <div className="message">{renderEmoji(props.message_group.message, 'g')}</div>
        <div className="created_at" title={props.message_group.created_at}>
          <span className='ago'>{timeAgo(props.message_group.created_at)}</span> 
        </div>{/* created_at */}
      </div>{/* message_content */}
    </Link>
  );
}

import './emoji.css';

// Shows emoji 20% larger than the text around them (backlog #51).
// The text is split into graphemes (what a reader sees as one character), so
// a family, a skin tone, a flag or a keycap stays one unit and is never cut in
// half. Runs of emoji share one span. Plain text is returned as plain strings,
// so React still escapes everything (no HTML string, no XSS).
// Browsers without Intl.Segmenter get the text back unchanged.
const SEGMENTER = (typeof Intl !== 'undefined' && Intl.Segmenter)
  ? new Intl.Segmenter(undefined, { granularity: 'grapheme' })
  : null;

// Emoji_Presentation: characters drawn as emoji by default (smileys, balloons).
// U+FE0F: the "show as emoji" selector (a red heart, a victory hand).
// Regional indicators: flags. U+20E3: keycaps (the boxed 1).
// Plain digits, #, (c), (r) and (tm) stay normal text. Escapes keep this
// file pure ASCII so no invisible character can be lost when it is copied.
const IS_EMOJI = /\p{Emoji_Presentation}|\uFE0F|\p{Regional_Indicator}|\u20E3/u;

export function renderEmoji(text, keyPrefix) {
  if (typeof text !== 'string' || text === '' || !SEGMENTER) {
    return text;
  }
  const out = [];
  let plain = '';
  let emoji = '';
  const flushEmoji = () => {
    if (emoji) {
      out.push(<span className='cruddur_emoji' key={`${keyPrefix}-${out.length}`}>{emoji}</span>);
      emoji = '';
    }
  };
  for (const { segment } of SEGMENTER.segment(text)) {
    if (IS_EMOJI.test(segment)) {
      if (plain) {
        out.push(plain);
        plain = '';
      }
      emoji += segment;
    } else {
      flushEmoji();
      plain += segment;
    }
  }
  flushEmoji();
  if (plain) {
    out.push(plain);
  }
  return out;
}

/* Emoji 20% larger than the surrounding text (backlog #51). line-height: 1
   keeps a line that contains an emoji from pushing the lines around it apart. */
.cruddur_emoji {
  font-size: 1.2em;
  line-height: 1;
}
